fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows and columns in the input matrix
    let rows = arr.len();
    // Safe to unwrap because the problem guarantees at least one row
    let cols = arr[0].len();

    // Prepare the output matrix with `cols` rows, each with capacity for `rows` elements
    let mut result = Vec::with_capacity(cols);

    // Build each row of the transposed matrix
    for j in 0..cols {
        let mut new_row = Vec::with_capacity(rows);
        for i in 0..rows {
            // The element at (i, j) in the input becomes (j, i) in the output
            new_row.push(arr[i][j]);
        }
        result.push(new_row);
    }

    result
}

